@CrossOrigin
@RestController
@RequestMapping("/BOMQuery")
public class BOMQueryRestController extends BaseSpringRestController {
	
	public BOMQueryRestController( BOMService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a BOM using a UUID
     * @param		UUID bOMId
     * @return		BOM
     */    
    @GetMapping("/load")
    public BOM load( @RequestParam(required=true) UUID bOMId ) {
    	BOM entity = null;

    	try {  
    		entity = service.getBOM( new BOMFetchOneSummary( bOMId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load BOM using Id " + bOMId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all BOM business objects
     * @return		Set<BOM>
     */
    @GetMapping("/")
    public List<BOM> loadAll() {                
    	List<BOM> bOMList = null;
        
    	try {
            // load the BOM
            bOMList = service.getAllBOM();
            
            if ( bOMList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all BOMs" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all BOMs ", exc );
        	return null;
        }

        return bOMList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected BOM bOM = null;
    protected BOMService service = null;
    private static final Logger LOGGER = Logger.getLogger(BOMQueryRestController.class.getName());
    
}
